import pandas as pd
import numpy as np

# Load the data
data = pd.read_csv('chunks_csv/bivariate/bivariate_ghg_waste.csv')
adjacency = pd.read_csv('chunks_csv/borough_adjacency.csv')

# Handle missing values
data['Waste_value'] = data['Waste_value'].fillna(data['Waste_value'].mean())

# Create a spatial weights matrix
adjacency_matrix = {}
for index, row in adjacency.iterrows():
    if row['borough'] not in adjacency_matrix:
        adjacency_matrix[row['borough']] = []
    adjacency_matrix[row['borough']].append(row['neighbor'])

# Calculate the Moran's I statistic
ghg_values = data['GHG_value'].values
waste_values = data['Waste_value'].values

moran_i = 0
for i in range(len(ghg_values)):
    for j in range(len(ghg_values)):
        if i != j:
            moran_i += (ghg_values[i] - np.mean(ghg_values)) * (waste_values[j] - np.mean(waste_values)) / (len(ghg_values) - 1)

# Perform a permutation test
p_value = 0
for _ in range(500):
    waste_values_permuted = np.random.permutation(waste_values)
    moran_i_permuted = 0
    for i in range(len(ghg_values)):
        for j in range(len(ghg_values)):
            if i != j:
                moran_i_permuted += (ghg_values[i] - np.mean(ghg_values)) * (waste_values_permuted[j] - np.mean(waste_values_permuted)) / (len(ghg_values) - 1)
    p_value += moran_i_permuted >= moran_i

p_value /= 500

# Determine the significance of the relationship
if p_value < 0.05:
    print(f"FINAL ANSWER: POSITIVE (test statistic = {moran_i}, p = {p_value})")
else:
    print(f"FINAL ANSWER: NOT SIGNIFICANT (test statistic = {moran_i}, p = {p_value})")

# Print the number of data points used
data_points_used = len(data)
print(f"data_points_used = {data_points_used}")
